import type { Line, TimelineEntry } from "../types";

// A handful of one-off volume covers that predate the Amazon-hosted-URL
// convention most coverUrl fields below use (see the comment near the
// bottom of this file) -- these three were never migrated, so they're
// plain imported assets instead, same as any other static image in the app.
import ghostRiderBadToTheBoneCover from "../assets/covers/Ghost Rider - Bad to the Bone.jpg";
import punisherCapitalPunishmentCover from "../assets/covers/Punisher - Capital Punishment.jpg";
import punisherSurvivalCover from "../assets/covers/Punisher - Survival.jpg";

// Bulk-wired from src/assets/Marvel/epic classic/<Character>.png (Nick dropped
// in a folder of per-line icons). Eagerly globbed so new files just need to
// match a line's name -- no import list to maintain by hand.
const marvelIconModules = import.meta.glob("../assets/Marvel/epic classic/*.png", {
  eager: true,
  import: "default",
}) as Record<string, string>;

function marvelIcon(filename: string): string {
  const key = `../assets/Marvel/epic classic/${filename}`;
  const url = marvelIconModules[key];
  if (!url) throw new Error(`Missing Marvel icon: ${key}`);
  return url;
}

// Seed data for the "Classic Marvel Epic Collection" page, bulk-imported from
// Nick's tracking spreadsheet ("Epic" tab). Replaces the earlier two-volume
// Fantastic Four pilot sample.
//
// Line colors are a visual read of that sheet's per-character cell fill, same
// approach as DC Finest -- lower confidence here though, 45 lines is a lot of
// similar blues/greens/golds/blacks to distinguish by eye. Fantastic Four keeps
// its previously-confirmed #00ADEF. Treat the rest as a first pass to verify.
//
// Debut dates are real-world first appearances for character lines; team/
// anthology titles with no single character (Marvel Two-In-One, Power Man and
// Iron Fist, Thunderbolts, X-Factor, X-Force) fall back to that book's own
// launch date -- see FALLBACK comments below.
//
// Ownership: sheet has separate Own/Digi/Omni/Read checkboxes. Own -> shelved,
// Digi or Omni (owned in another format, no physical Epic Collection) ->
// alt_format, otherwise announced. Read wasn't imported (same call as DC Finest).
//
// creators/description aren't in the source spreadsheet -- most have been
// filled in since, but a handful are still blank (same known-gap treatment as
// cover images, see README).
//
// releaseDate/writers/artists were bulk-backfilled from the "Epic Collections"
// tables on https://en.wikipedia.org/wiki/Marvel_Epic_Collection -- that
// article carries Writers/Artists/Released columns per volume. releaseDate is
// the FIRST printing: Wikipedia lists one row per printing (Amazing
// Spider-Man Vol. 1 has 2014/2020/2022 rows sharing rowspan'd metadata), and
// the earliest date is the one kept. Two volumes have no date because the
// article has none for them: Venom Vol. 8 isn't listed at all, and Master of
// Kung Fu Vol. 3 is marked "Cancelled" there (worth a look -- it's still
// listed as a live volume here).
